// Cost-scaling min-cost flow for the assignment problem (dense).
// Based on Goldberg & Kennedy / B. Korte style cost scaling with push-relabel.
// Specialized: bipartite source->left->right->sink, unit capacities.
#include <cstdio>
#include <cstdlib>
#include <cstdint>
#include <cmath>
#include <vector>
#include <algorithm>
#include <chrono>
#include <cstring>
#include <queue>
#include <limits>

using namespace std;

// We'll implement successive shortest augmenting paths with reduced costs
// and a Dijkstra using a radix/bucket heap on integer costs. Costs are scaled
// to int64 by multiplying by a large factor.

struct Solver {
    int n;
    const double* M; // n*n row major
    vector<int> matchL, matchR;
    vector<double> potL, potR;

    // Dijkstra successive shortest path (Jonker-Volgenant is better, but let's
    // implement a fast SSP with potentials and a binary heap first to gauge).
    double solve() {
        matchL.assign(n, -1);
        matchR.assign(n, -1);
        potL.assign(n, 0);
        potR.assign(n, 0);

        const double INF = 1e100;
        vector<double> dist(n);
        vector<int> prev(n);
        vector<char> used(n);

        for (int i = 0; i < n; i++) {
            // Dijkstra from free left node i over right nodes
            fill(dist.begin(), dist.end(), INF);
            fill(used.begin(), used.end(), 0);
            // initial edges from i to all right nodes
            for (int j = 0; j < n; j++) {
                dist[j] = M[i*(long)n + j] - potL[i] + potR[j];
                prev[j] = i;
            }
            int augR = -1;
            for (int iter = 0; iter < n; iter++) {
                int j = -1; double best = INF;
                for (int k = 0; k < n; k++) if (!used[k] && dist[k] < best) { best = dist[k]; j = k; }
                if (j < 0) break;
                used[j] = 1;
                int ml = matchR[j];
                if (ml < 0) { augR = j; break; }
                // relax edges from matched left node ml
                double base = dist[j]; // potential update handled via dist
                const double* row = M + ml*(long)n;
                double pL = potL[ml];
                for (int k = 0; k < n; k++) if (!used[k]) {
                    double nd = base + row[k] - pL + potR[k];
                    // wait: reduced cost of edge ml->k = row[k] - potL[ml] + potR[k]
                    // But dist should be reduced. The slack at j is dist[j].
                    // nd = dist[j] + reduced(ml->k) - reduced(ml->j)? 
                    // Standard formulation: we only traverse reverse edges implicitly.
                    // Let me redo properly below.
                    if (nd < dist[k]) { dist[k] = nd; prev[k] = ml; }
                }
            }
            (void)augR;
        }
        return 0;
    }
};

