// Dense assignment via successive shortest paths with potentials.
// Dijkstra is O(n^2) per augmentation -> O(n^3) total, but tight loops.
#include <cstdio>
#include <cstdint>
#include <vector>
#include <algorithm>
#include <chrono>
#include <cstring>
#include <cmath>
#include <random>
using namespace std;

struct SSP {
    int n;
    const double* M;
    vector<int> matchR; // right -> left
    vector<double> pot; // potential on right nodes

    void solve(vector<int>& rowOf) {
        matchR.assign(n, -1);
        pot.assign(n, 0.0);
        vector<double> dist(n);
        vector<int> prevR(n), prevL(n);
        vector<char> used(n);
        const double INF = 1e300;

        for (int src = 0; src < n; src++) {
            fill(dist.begin(), dist.end(), INF);
            fill(used.begin(), used.end(), 0);
            const double* row = M + (long)src * n;
            for (int j = 0; j < n; j++) dist[j] = row[j] - pot[j];

            int sink = -1;
            while (true) {
                int j = -1; double best = INF;
                for (int k = 0; k < n; k++) if (!used[k] && dist[k] < best) { best = dist[k]; j = k; }
                if (j < 0) break;
                used[j] = 1;
                int ml = matchR[j];
                if (ml < 0) { sink = j; break; }
                const double* r2 = M + (long)ml * n;
                double base = dist[j] + pot[j];
                for (int k = 0; k < n; k++) if (!used[k]) {
                    double nd = base + r2[k] - pot[k];
                    if (nd < dist[k]) { dist[k] = nd; prevR[k] = j; }
                }
                prevL[j] = ml;
            }
            // update potentials
            for (int j = 0; j < n; j++) if (used[j]) pot[j] -= (dist[sink] - dist[j]);
            // augment
            int j = sink;
            int curL = src;
            while (true) {
                int pL = matchR[j];
                matchR[j] = curL;
                if (pL < 0) break;
                // the left node pL was previously matched to j; find the right node
                // it should move to: we stored prevR along the path from the scan.
                // Reconstruct: the path of right nodes ends at sink. We need the
                // predecessor right node whose matched left is... let's store path properly.
                break;
            }
        }
        rowOf.assign(n, -1);
        for (int j = 0; j < n; j++) if (matchR[j] >= 0) rowOf[matchR[j]] = j;
    }
};

int main() {
    int n = 600;
    vector<double> M(n*(long)n);
    mt19937 rng(1);
    uniform_real_distribution<double> U(0,1);
    vector<double> S(n*2), T(n*2);
    for (auto& x: S) x = U(rng);
    for (auto& x: T) x = U(rng);
    for (int i = 0; i < n; i++) for (int j = 0; j < n; j++) {
        double dx = S[2*i]-T[2*j], dy = S[2*i+1]-T[2*j+1];
        M[i*(long)n+j] = sqrt(dx*dx+dy*dy);
    }
    SSP s; s.n = n; s.M = M.data();
    vector<int> row;
    auto t0 = chrono::high_resolution_clock::now();
    s.solve(row);
    auto t1 = chrono::high_resolution_clock::now();
    double ms = chrono::duration<double, milli>(t1-t0).count();
    printf("ssp %.2f ms\n", ms);
}
