// Dense assignment: successive shortest paths + potentials, O(n^3) tight loops.
#include <cstdio>
#include <cstdint>
#include <vector>
#include <algorithm>
#include <chrono>
#include <cstring>
#include <cmath>
#include <random>
using namespace std;

// matchR[j] = left node matched to right j, or -1
// Returns column chosen for each row.
void assign(int n, const double* M, int* colOf) {
    vector<int> matchR(n, -1);
    vector<double> pot(n, 0.0);
    vector<double> dist(n);
    vector<int> parent(n);      // parent right-node on shortest path tree
    vector<int> parentL(n);     // left node used to reach this right node
    vector<char> used(n);

    for (int src = 0; src < n; src++) {
        fill(dist.begin(), dist.end(), 1e300);
        fill(used.begin(), used.end(), 0);
        const double* row = M + (long)src * n;
        for (int j = 0; j < n; j++) {
            dist[j] = row[j] - pot[j];
            parentL[j] = src;
            parent[j] = -1;
        }
        int sink = -1;
        while (true) {
            int j = -1; double best = 1e300;
            for (int k = 0; k < n; k++) if (!used[k] && dist[k] < best) { best = dist[k]; j = k; }
            used[j] = 1;
            int ml = matchR[j];
            if (ml < 0) { sink = j; break; }
            const double* r2 = M + (long)ml * n;
            double base = dist[j] + pot[j];
            for (int k = 0; k < n; k++) if (!used[k]) {
                double nd = base + r2[k] - pot[k];
                if (nd < dist[k]) { dist[k] = nd; parentL[k] = ml; parent[k] = j; }
            }
        }
        double ds = dist[sink];
        for (int j = 0; j < n; j++) if (used[j]) pot[j] += dist[j] - ds;

        // augment along path
        int j = sink;
        while (j != -1) {
            int L = parentL[j];
            int pj = parent[j];
            matchR[j] = L;
            j = pj;
        }
    }
    fill(colOf, colOf + n, -1);
    for (int j = 0; j < n; j++) colOf[matchR[j]] = j;
}

int main() {
    int n = 600;
    vector<double> M(n*(long)n);
    mt19937 rng(1);
    uniform_real_distribution<double> U(0,1);
    vector<double> S(n*2), T(n*2);
    for (auto& x: S) x = U(rng);
    for (auto& x: T) x = U(rng);
    for (int i = 0; i < n; i++) for (int j = 0; j < n; j++) {
        double dx = S[2*i]-T[2*j], dy = S[2*i+1]-T[2*j+1];
        M[i*(long)n+j] = sqrt(dx*dx+dy*dy);
    }
    vector<int> col(n);
    auto t0 = chrono::high_resolution_clock::now();
    assign(n, M.data(), col.data());
    auto t1 = chrono::high_resolution_clock::now();
    printf("ssp %.2f ms\n", chrono::duration<double, milli>(t1-t0).count());
    double cost = 0;
    for (int i = 0; i < n; i++) cost += M[i*(long)n + col[i]];
    printf("cost %.6f\n", cost);
    // dump assignment for python check
    FILE* f = fopen("build/col.txt","w");
    for (int i = 0; i < n; i++) fprintf(f, "%d\n", col[i]);
    fclose(f);
    // also dump M? too big. python regenerates same points.
}
