// matchL[i] = column matched to row i
void assign(int n, const double* M, int* colOf) {
    vector<int> matchL(n, -1), matchR(n, -1);
    vector<double> potR(n, 0.0);
    vector<double> dist(n);
    vector<int> pred(n);   // predecessor left-node for each right node in the tree
    vector<char> used(n);

    for (int src = 0; src < n; src++) {
        fill(dist.begin(), dist.end(), 1e300);
        fill(used.begin(), used.end(), 0);
        const double* row = M + (long)src * n;
        for (int j = 0; j < n; j++) { dist[j] = row[j] - potR[j]; pred[j] = src; }

        int sink = -1;
        while (true) {
            int j = -1; double best = 1e300;
            for (int k = 0; k < n; k++) if (!used[k] && dist[k] < best) { best = dist[k]; j = k; }
            used[j] = 1;
            int ml = matchR[j];
            if (ml < 0) { sink = j; break; }
            // traverse reverse edge j -> ml (cost 0 in residual) then forward ml -> k
            const double* r2 = M + (long)ml * n;
            // reduced cost of forward edge ml->k: r2[k] - potL[ml] + potR[k]
            // potL[ml] = r2[matchL[ml]] + potR[matchL[ml]]? We can derive:
            // At optimality for matched edge, reduced cost is 0:
            //   M[ml, j] - potL[ml] + potR[j] = 0  => potL[ml] = M[ml, j] + potR[j]
            // so reduced(ml->k) = r2[k] - (M[ml,j] + potR[j]) + potR[k]
            // nd = dist[j] + reduced(ml->k) = dist[j] + r2[k] - M[ml,j] - potR[j] + potR[k]
            double mjj = M[(long)ml * n + j];
            double base = dist[j] - mjj - potR[j];
            for (int k = 0; k < n; k++) if (!used[k]) {
                double nd = base + r2[k] + potR[k];
                if (nd < dist[k]) { dist[k] = nd; pred[k] = ml; }
            }
        }
        // update potentials: potR[j] += dist[j] - dist[sink] for scanned j
        double ds = dist[sink];
        for (int j = 0; j < n; j++) if (used[j]) potR[j] += dist[j] - ds;

        // augment: walk from sink back via matched edges
        int j = sink;
        while (true) {
            int L = pred[j];
            int prevj = matchL[L];
            matchL[L] = j;
            matchR[j] = L;
            if (L == src) break;
            j = prevj;
        }
    }
    for (int i = 0; i < n; i++) colOf[i] = matchL[i];
}

