#include <cstdio>
#include <cstdint>
#include <vector>
#include <algorithm>
#include <chrono>
#include <cstring>
using namespace std;

// Assignment on a sparse candidate graph: each left node connects to its k nearest.
// If no perfect matching exists, returns false.
bool assign_knn(int n, const double* M, int k, int* colOf) {
    // candidate columns per row
    vector<int> cand(n * (long)k);
    vector<double> crow(n);
    for (int i = 0; i < n; i++) {
        const double* row = M + (long)i * n;
        // partial select k smallest via nth_element on index array
        vector<int> idx(n);
        iota(idx.begin(), idx.end(), 0);
        nth_element(idx.begin(), idx.begin()+k, idx.end(), [&](int a, int b){ return row[a] < row[b]; });
        sort(idx.begin(), idx.begin()+k); // not required
        memcpy(&cand[i*(long)k], idx.data(), k*sizeof(int));
    }
    // adjacency: for residual reverse edges we need, for each right node, list of left nodes that have it as candidate
    vector<vector<int>> radj(n);
    for (int i = 0; i < n; i++) for (int t = 0; t < k; t++) radj[cand[i*(long)k + t]].push_back(i);

    vector<int> matchL(n, -1), matchR(n, -1);
    vector<double> potR(n, 0.0);

    vector<double> dist(n, 1e300);
    vector<int> pred(n, -1);
    vector<char> used(n, 0);
    // dial/bucket? use a simple label-setting over only candidate edges via a binary heap of right nodes.
    // Since graph is sparse (k per node), Dijkstra with a heap over reached right nodes.
    struct Node { double d; int v; bool operator<(const Node& o) const { return d > o.d; } };

    for (int src = 0; src < n; src++) {
        // reset only touched nodes
        vector<int> touched;
        auto relax = [&](int j, double nd, int fromL) {
            if (nd < dist[j]) {
                if (dist[j] > 1e299) touched.push_back(j);
                dist[j] = nd; pred[j] = fromL;
            }
        };
        const double* row = M + (long)src * n;
        int* cc = &cand[src*(long)k];
        for (int t = 0; t < k; t++) relax(cc[t], row[cc[t]] - potR[cc[t]], src);

        priority_queue<Node> pq;
        for (int j : touched) pq.push({dist[j], j});
        int sink = -1;
        while (!pq.empty()) {
            auto [d, j] = pq.top(); pq.pop();
            if (d != dist[j] || used[j]) continue;
            used[j] = 1;
            int ml = matchR[j];
            if (ml < 0) { sink = j; break; }
            const double* r2 = M + (long)ml * n;
            double mjj = M[(long)ml * n + j];
            double base = dist[j] - mjj + potR[j];
            int* c2 = &cand[ml*(long)k];
            for (int t = 0; t < k; t++) {
                int kk = c2[t];
                if (used[kk]) continue;
                double nd = base + r2[kk] - potR[kk];
                if (nd < dist[kk]) {
                    if (dist[kk] > 1e299) touched.push_back(kk);
                    dist[kk] = nd; pred[kk] = ml;
                    pq.push({nd, kk});
                }
            }
        }
        if (sink < 0) {
            // cleanup and fail
            for (int j : touched) { dist[j] = 1e300; used[j] = 0; }
            return false;
        }
        double ds = dist[sink];
        for (int j : touched) {
            if (used[j]) potR[j] += dist[j] - ds;
            dist[j] = 1e300; used[j] = 0;
        }
        int j = sink;
        while (true) {
            int L = pred[j];
            int prevj = matchL[L];
            matchL[L] = j; matchR[j] = L;
            if (L == src) break;
            j = prevj;
        }
    }
    for (int i = 0; i < n; i++) colOf[i] = matchL[i];
    return true;
}
