// Jonker-Volgenant / LAPJV algorithm for the dense assignment problem.
// Adapted from the public-domain description; integer-free double version.
#include <cstdio>
#include <cstdint>
#include <vector>
#include <algorithm>
#include <chrono>
#include <cstring>
#include <cmath>
#include <limits>
using namespace std;

static void lapjv(int n, const double* cost, int* rowsol) {
    const double INF = 1e18;
    vector<double> u(n, 0), v(n, 0);
    vector<int> cols(n, -1); // column -> row
    vector<double> d(n);
    vector<int> pred(n);
    vector<char> seen(n);

    for (int i = 0; i < n; i++) {
        // column reduction style init: find min reduced cost column
        int jmin = 0; double vmin = cost[i*(long)n] - v[0];
        for (int j = 1; j < n; j++) {
            double val = cost[i*(long)n + j] - v[j];
            if (val < vmin) { vmin = val; jmin = j; }
        }
        u[i] = vmin;
        // if free, assign
        if (cols[jmin] < 0) { cols[jmin] = i; rowsol[i] = jmin; }
        else rowsol[i] = -1;
    }
    // now augment for unassigned rows using Dijkstra shortest paths
    vector<int> free_rows;
    for (int i = 0; i < n; i++) if (rowsol[i] < 0) free_rows.push_back(i);
    // Actually the init above may assign the same column to conceptually conflicting rows;
    // cols[] tracks the last row that claimed it. Rows with rowsol==-1 need augmentation,
    // but also the row stored in cols is matched. Good.

    for (int fi = 0; fi < (int)free_rows.size(); fi++) {
        int src = free_rows[fi];
        fill(d.begin(), d.end(), INF);
        fill(seen.begin(), seen.end(), 0);
        for (int j = 0; j < n; j++) { d[j] = cost[(long)src*n + j] - u[src] - v[j]; pred[j] = src; }
        int sink = -1;
        while (true) {
            int j = -1; double best = INF;
            for (int k = 0; k < n; k++) if (!seen[k] && d[k] < best) { best = d[k]; j = k; }
            seen[j] = 1;
            int i2 = cols[j];
            if (i2 < 0) { sink = j; break; }
            double base = d[j];
            const double* r2 = cost + (long)i2 * n;
            // reduced cost i2->k = r2[k] - u[i2] - v[k]; u[i2] = r2[j] - v[j] (matched, rc 0)
            // nd = base + r2[k] - u[i2] - v[k] = base + r2[k] - (r2[j] - v[j]) - v[k]
            double u_i2 = r2[j] - v[j];
            for (int k = 0; k < n; k++) if (!seen[k]) {
                double nd = base + r2[k] - u_i2 - v[k];
                if (nd < d[k]) { d[k] = nd; pred[k] = i2; }
            }
        }
        double ds = d[sink];
        for (int j = 0; j < n; j++) if (seen[j]) v[j] += d[j] - ds;
        u[src] += ds; // not strictly needed
        int j = sink;
        while (true) {
            int i2 = pred[j];
            int pj = rowsol[i2];
            rowsol[i2] = j; cols[j] = i2;
            if (i2 == src) break;
            j = pj;
        }
    }
}

int main() {
    int n = 600;
    vector<double> M(n*(long)n);
    FILE* f = fopen("build/M.bin","rb"); fread(M.data(),8,n*(long)n,f); fclose(f);
    vector<int> col(n,-1);
    auto t0 = chrono::high_resolution_clock::now();
    lapjv(n, M.data(), col.data());
    auto t1 = chrono::high_resolution_clock::now();
    printf("%.3f ms\n", chrono::duration<double,milli>(t1-t0).count());
    FILE* o = fopen("build/col.bin","wb"); fwrite(col.data(),4,n,o); fclose(o);
}
