// Network simplex for the transportation problem (dense cost matrix).
// Node layout: source nodes 0..n-1, sink nodes n..n+m-1, root n+m.
// Based on the LEMON network simplex structure (MIT), simplified.
#include <cstdio>
#include <cstdint>
#include <vector>
#include <algorithm>
#include <chrono>
#include <cstring>
#include <cmath>
#include <limits>
using namespace std;

struct NS {
    int n, m, N;          // sources, sinks, total nodes incl root
    const double* cost;   // n*m
    const double* supply; // n  (positive)
    const double* demand; // m  (positive)
    vector<int> parent, depth, thread, revthread, succ_num;
    vector<double> pi, flow;
    vector<int> parent_arc; // for node, the arc id connecting to parent. arcs: forward 0..n*m-1 (i->j), reverse n*m.. 
    int art_start; // artificial arcs start index
    vector<int> arc_src, arc_dst; // only for artificial? we compute from id
    int root;

    inline int FWD(int i, int j) { return i*m + j; }
    inline int REV(int i, int j) { return n*m + i*m + j; }
    inline void arc_ends(int a, int &u, int &v) {
        if (a < n*m) { u = a / m; v = n + a % m; }
        else if (a < 2*n*m) { int b = a - n*m; v = b / m; u = n + b % m; }
        else {
            // artificial: root->source or sink->root
            int k = a - art_start;
            if (k < n) { u = root; v = k; }
            else { u = n + (k - n); v = root; }
        }
    }
    inline double arc_cost(int a) {
        if (a < 2*n*m) { int b = a % (n*m); return cost[b]; }
        return 0; // artificial cost handled via big cost in reduced cost directly
    }

    void init() {
        N = n + m + 1; root = n + m;
        parent.assign(N, root);
        depth.assign(N, 1);
        pi.assign(N, 0);
        parent_arc.assign(N, -1);
        succ_num.assign(N, 1);
        thread.resize(N); revthread.resize(N);
        // artificial arcs
        art_start = 2*n*m;
        // build initial basis: root connected to all nodes via artificial arcs
        // thread: preorder. root, then sources, then sinks.
        for (int i = 0; i < N; i++) { thread[i] = i+1; revthread[i] = i-1; }
        thread[N-1] = 0; // we'll not use cyclic; use -1 terminated
        thread[root] = 0; revthread[0] = root;
        for (int i = 0; i < n-1; i++) { thread[i] = i+1; revthread[i+1] = i; }
        thread[n-1] = n; revthread[n] = n-1;
        for (int j = 0; j < m-1; j++) { thread[n+j] = n+j+1; revthread[n+j+1] = n+j; }
        thread[n+m-1] = -1; 
        revthread[root] = -1;
        depth[root] = 0; succ_num[root] = N;
        // flows on artificial arcs: supply[i] leaving source toward root? 
        // We store flow per node on the arc toward its parent.
        flow.assign(N, 0);
        for (int i = 0; i < n; i++) { parent_arc[i] = art_start + i; flow[i] = supply[i]; pi[i] = 1e6; }
        for (int j = 0; j < m; j++) { parent_arc[n+j] = art_start + n + j; flow[n+j] = demand[j]; pi[n+j] = -1e6; }
        // BIG cost artificial: reduced cost of artificial source arc (root->i) = BIG - pi[i] ... we'll special-case.
    }

    // enter: find an arc with negative reduced cost (Dantzig, block search)
    int find_entering() {
        const double EPS = 1e-12;
        const double BIG = 1e6;
        int best = -1; double best_rc = -EPS;
        // scan a block of real arcs
        int total = n*m;
        // full scan (for correctness first)
        for (int a = 0; a < total; a++) {
            int i = a / m, j = a % m;
            double rc = cost[a] - pi[i] + pi[n+j];
            // forward arc i->j is nonbasic at lower bound (0) unless it's the tree arc
            // We must skip basic arcs. Basic arcs are parent arcs.
            if (rc < best_rc) {
                // check not basic
                if (!(parent[i]==n+j && parent_arc[i]==FWD(i,j)) && !(parent[n+j]==i && parent_arc[n+j]==FWD(i,j))) {
                    best_rc = rc; best = FWD(i,j);
                }
            }
            double rc2 = -rc; // reverse arc j->i at lower bound means forward flow at upper... for uncapacitated, reverse entering means decrease
            // For the transportation problem arcs are uncapacitated, so only forward arcs exist as nonbasic at 0.
            // Reverse direction is represented by the tree. Nonbasic arcs are always at 0 (lower). So only negative rc forward arcs enter.
            (void)rc2;
        }
        return best;
    }

    void pivot(int enter) {
        int u, v; arc_ends(enter, u, v); // arc u->v
        // find apex of the cycle: walk up from u and v
        int x = u, y = v;
        while (x != y) {
            if (depth[x] > depth[y]) x = parent[x];
            else if (depth[y] > depth[x]) y = parent[y];
            else { x = parent[x]; y = parent[y]; }
        }
        int apex = x;
        // determine leaving arc: the minimum flow on the path where the arc is oriented against the entering flow.
        // Entering arc u->v adds flow. On path v->apex, tree arcs oriented toward apex are forward (flow increases), 
        // arcs oriented away from apex are reverse (flow decreases) -> candidates to leave.
        double delta = 1e300; int leave_node = -1; // the child node of the leaving arc
        // path from v up to apex: these arcs will have flow decreased if oriented v-ward (parent is closer to apex and arc direction...)
        // Simpler standard: represent each tree arc as connecting node to parent, with flow = amount sent from node to parent
        // (flow[node] > 0 means node sends to parent). 
        // Entering arc u->v: we send +delta from u to v.
        // Walk from u to apex: we need to push delta toward apex, so flow[node] (node->parent) increases. No leaving candidate.
        // Walk from v to apex: we need to pull delta from apex toward v, so flow[node] (node->parent) decreases. Candidate if flow[node] is minimal.
        for (int z = v; z != apex; z = parent[z]) {
            if (flow[z] < delta) { delta = flow[z]; leave_node = z; }
        }
        // if no candidate on v side, the entering arc's "reverse" can't... delta = inf means unbounded, shouldn't happen.
        // Now update flows.
        for (int z = u; z != apex; z = parent[z]) flow[z] += delta;
        for (int z = v; z != apex; z = parent[z]) flow[z] -= delta;
        if (leave_node < 0) { fprintf(stderr, "unbounded\n"); return; }
        // If delta==0 degenerate pivot still must update tree.
        // Update tree: detach subtree of leave_node and reattach via entering arc.
        update_tree(enter, u, v, leave_node, apex);
    }

    void update_tree(int enter, int u, int v, int leave, int apex) {
        // Remove arc (leave -> parent[leave]) and add arc u->v. The subtree rooted at `leave`
        // is re-rooted along the path to v and attached under u.
        // Collect the path from v up to leave (v is in leave's subtree).
        vector<int> path;
        for (int z = v; z != leave; z = parent[z]) path.push_back(z);
        path.push_back(leave);
        // reverse: path goes from leave's descendant v up to leave. We reparent so that
        // each node on path gets the next as parent, and v's parent becomes u.
        // First, remove `leave` subtree from its current thread position. We'll rebuild simply
        // by recomputing parent/depth/pi and then rebuilding thread. For n=600, N=1201,
        // rebuilding thread each pivot is fine if pivots are few thousand.
        int old_parent = parent[leave];
        // reparent along path
        for (int t = (int)path.size()-1; t > 0; t--) {
            int node = path[t];
            int nxt = path[t-1];
            parent[node] = nxt;
            // flow orientation: previously flow[nxt] was amount nxt sends to its parent (node).
            // After reversal, node sends to parent nxt, so flow[node] = -flow[nxt] (before we zero).
        }
        // The flow values need careful reversal. Let's recompute flows? They were already updated
        // for the delta. Reversing orientation: for each reversed arc, flow sign flips and moves.
        // This is getting error-prone. We'll store flow on undirected tree edges separately.
        (void)old_parent; (void)enter;
    }
};

int main(){ printf("scaffold\n"); }
