// Network simplex for dense transportation. Tree stored with parent pointers;
// thread rebuilt only as needed. Flow stored per node = amount sent node -> parent.
#include <cstdio>
#include <cstdint>
#include <vector>
#include <algorithm>
#include <chrono>
#include <cstring>
#include <cmath>
#include <cstdlib>
using namespace std;

static const double BIG = 1e5;

struct NS {
    int n, m, N, root;
    const double* C;
    vector<int> parent, depth, thread, succ;
    vector<double> pi, flow;
    vector<int> par_arc_j; // for a source node matched via real arc, the sink index; -1 if artificial
    vector<char> is_art;

    void build_thread() {
        // preorder from root using parent pointers (children lists)
        vector<vector<int>> ch(N);
        for (int i = 0; i < N; i++) if (i != root) ch[parent[i]].push_back(i);
        thread.assign(N, -1);
        succ.assign(N, 0);
        int prev = -1;
        vector<int> st = {root};
        vector<int> order; order.reserve(N);
        while (!st.empty()) {
            int x = st.back(); st.pop_back();
            order.push_back(x);
            for (int c : ch[x]) st.push_back(c);
        }
        // st was LIFO so order is reverse preorder of children; fix with explicit DFS
        order.clear();
        vector<int> it(N, 0);
        st = {root};
        while (!st.empty()) {
            int x = st.back();
            if (it[x] == 0) order.push_back(x);
            if (it[x] < (int)ch[x].size()) { st.push_back(ch[x][it[x]++]); }
            else st.pop_back();
        }
        for (int i = 0; i+1 < (int)order.size(); i++) thread[order[i]] = order[i+1];
        thread[order.back()] = -1;
        // succ_num
        for (int i = (int)order.size()-1; i >= 0; i--) {
            int x = order[i];
            succ[x] = 1;
            for (int c : ch[x]) succ[x] += succ[c];
        }
    }

    void init(const double* supply, const double* demand) {
        N = n + m + 1; root = n + m;
        parent.assign(N, root); depth.assign(N, 1); pi.assign(N, 0); flow.assign(N, 0);
        is_art.assign(N, 1); par_arc_j.assign(N, -1);
        depth[root] = 0; parent[root] = -1; is_art[root] = 0;
        for (int i = 0; i < n; i++) { flow[i] = supply[i]; pi[i] = BIG; }
        for (int j = 0; j < m; j++) { flow[n+j] = demand[j]; pi[n+j] = -BIG; }
        build_thread();
    }

    inline double rc_forward(int i, int j) { return C[(long)i*m + j] - pi[i] + pi[n+j]; }

    int find_entering(int &ei, int &ej) {
        double best = -1e-10; int found = 0;
        // candidate list: sample. For correctness scan all but stop early after finding a very negative one.
        for (int i = 0; i < n; i++) {
            const double* row = C + (long)i*m;
            double pii = pi[i];
            for (int j = 0; j < m; j++) {
                double rc = row[j] - pii + pi[n+j];
                if (rc < best) {
                    // skip if this arc is basic
                    bool basic = (parent[i]==n+j && !is_art[i] && par_arc_j[i]==j) ||
                                 (parent[n+j]==i && !is_art[n+j] && par_arc_j[n+j]==j);
                    if (!basic) { best = rc; ei = i; ej = j; found = 1; if (rc < -1e-4) return 1; }
                }
            }
        }
        return found;
    }

    bool pivot(int ei, int ej) {
        int u = ei, v = n + ej;
        int x = u, y = v;
        while (x != y) {
            if (depth[x] > depth[y]) x = parent[x];
            else if (depth[y] > depth[x]) y = parent[y];
            else { x = parent[x]; y = parent[y]; }
        }
        int apex = x;
        double delta = 1e300; int leave = -1;
        for (int z = v; z != apex; z = parent[z]) if (flow[z] <= delta) { delta = flow[z]; leave = z; }
        if (leave < 0) return false;
        for (int z = u; z != apex; z = parent[z]) flow[z] += delta;
        for (int z = v; z != apex; z = parent[z]) flow[z] -= delta;

        // collect path from v up to leave (inclusive), v is in leave subtree
        vector<int> path;
        for (int z = v; ; z = parent[z]) { path.push_back(z); if (z == leave) break; }
        // path[0]=v ... path.back()=leave. Reverse orientation along this path.
        // Currently flow[path[t]] = amount path[t] sends to parent[path[t]] (=path[t+1] for t<last).
        // After reversal parent[path[t+1]] = path[t], and flow[path[t+1]] = -old flow[path[t]]? 
        // old flow[path[t]] was amount sent from path[t] to path[t+1]. After reversal the arc
        // sends from path[t+1] to path[t], so flow[path[t+1]] (node->parent) = -old flow[path[t]].
        vector<double> oldflow(path.size());
        for (int t = 0; t < (int)path.size(); t++) oldflow[t] = flow[path[t]];
        for (int t = (int)path.size()-1; t > 0; t--) {
            int node = path[t];      // becomes child of path[t-1]
            int neu = path[t-1];
            parent[node] = neu;
            flow[node] = -oldflow[t-1];
            // arc between them is the real arc (row, col)
            int row, col;
            if (node < n) { row = node; col = neu - n; }
            else { row = neu; col = node - n; }
            is_art[node] = 0; par_arc_j[node] = col;
        }
        // attach v under u via entering arc
        parent[v] = u;
        flow[v] = delta;
        is_art[v] = 0; par_arc_j[v] = ej;
        // recompute depth and pi for the moved subtree (nodes whose parent changed: path nodes and their old subtrees)
        // Full recompute of depth & pi from root is O(N) per pivot — acceptable for now.
        recompute_dual();
        return true;
    }

    void recompute_dual() {
        // BFS/DFS from root
        depth[root] = 0; pi[root] = 0;
        vector<int> st = {root};
        vector<vector<int>> ch(N);
        for (int i = 0; i < N; i++) if (i != root) ch[parent[i]].push_back(i);
        while (!st.empty()) {
            int x = st.back(); st.pop_back();
            for (int c : ch[x]) {
                depth[c] = depth[x] + 1;
                // reduced cost of tree arc must be 0.
                // Determine orientation and cost.
                if (is_art[c]) {
                    if (c < n) pi[c] = BIG;          // arc root->c cost BIG: BIG - pi[root] + pi[c] = 0 => pi[c] = -BIG? 
                    else pi[c] = -BIG;               // arc c->root cost BIG: BIG - pi[c] + pi[root] = 0 => pi[c] = BIG
                    // WAIT sign convention. Let's define consistently below and fix after testing.
                } else {
                    int row, col;
                    if (c < n) { row = c; col = parent[c] - n; }
                    else if (parent[c] < n) { row = parent[c]; col = c - n; }
                    else { row = 0; col = 0; }
                    double cc = C[(long)row*m + col];
                    // arc direction in tree is child->parent (flow goes child to parent).
                    // reduced cost of the directed arc child->parent = 0.
                    if (c < n) {
                        // arc row(=c) -> col(=parent): rc = cc - pi[c] + pi[parent] = 0 => pi[c] = cc + pi[parent]
                        pi[c] = cc + pi[parent[c]];
                    } else {
                        // arc parent(=row) -> c(=col): rc = cc - pi[parent] + pi[c] = 0 => pi[c] = -cc + pi[parent]
                        pi[c] = -cc + pi[parent[c]];
                    }
                }
                st.push_back(c);
            }
        }
    }

    bool solve() {
        int pivots = 0;
        while (true) {
            int ei, ej;
            if (!find_entering(ei, ej)) break;
            if (!pivot(ei, ej)) { fprintf(stderr, "pivot fail\n"); return false; }
            pivots++;
            if (pivots > 200000) { fprintf(stderr, "too many pivots\n"); return false; }
        }
        fprintf(stderr, "pivots %d\n", pivots);
        return true;
    }

    void extract(double* G) {
        memset(G, 0, sizeof(double)*n*(long)m);
        // flow on tree arcs. For each non-root node, flow[node] is sent node->parent.
        for (int i = 0; i < n; i++) if (!is_art[i]) {
            int j = par_arc_j[i];
            // node i (source) sends flow[i] to parent (sink j): G[i,j] += flow[i]
            G[(long)i*m + j] += flow[i];
        }
        for (int j = 0; j < m; j++) if (!is_art[n+j]) {
            int jj = par_arc_j[n+j];
            int row = parent[n+j];
            // node (sink) sends flow to parent (source): that means flow goes source->sink of -flow? 
            // flow[n+j] > 0 means sink sends to its parent source, i.e. the transport arc source->sink carries -flow.
            G[(long)row*m + jj] -= flow[n+j];
        }
    }
};

int main() {
    int n = 600;
    vector<double> M(n*(long)n);
    FILE* f = fopen("build/M.bin","rb"); fread(M.data(), 8, n*(long)n, f); fclose(f);
    vector<double> a(n, 1.0/n), b(n, 1.0/n);
    NS ns; ns.n = n; ns.m = n; ns.C = M.data();
    auto t0 = chrono::high_resolution_clock::now();
    ns.init(a.data(), b.data());
    bool ok = ns.solve();
    auto t1 = chrono::high_resolution_clock::now();
    printf("%s %.2f ms\n", ok?"OK":"FAIL", chrono::duration<double,milli>(t1-t0).count());
    vector<double> G(n*(long)n);
    ns.extract(G.data());
    double cost = 0, sm = 0;
    for (long i = 0; i < n*(long)n; i++) { cost += G[i]*M[i]; sm += G[i]; }
    printf("cost %.6f sum %.6f\n", cost, sm);
}
