// Optimized dense assignment (SSP + potentials).
void assign(int n, const double* M, int* colOf) {
    vector<int> matchL(n, -1), matchR(n, -1);
    vector<double> potR(n, 0.0), dist(n);
    vector<int> pred(n);
    vector<char> used(n);

