        const double* row = M + (long)src * n;
        for (int j = 0; j < n; j++) { dist[j] = row[j] - potR[j]; pred[j] = src; used[j] = 0; }

        int sink = -1;
        int scanned = 0;
        while (scanned < n) {
            int j = 0; double best = dist[0];
            // unrolled min scan
            int k = 0;
            for (; k + 7 < n; k += 8) {
                #define CHK(o) if (!used[k+o] && dist[k+o] < best) { best = dist[k+o]; j = k+o; }
                CHK(0) CHK(1) CHK(2) CHK(3) CHK(4) CHK(5) CHK(6) CHK(7)
                #undef CHK
            }
            for (; k < n; k++) if (!used[k] && dist[k] < best) { best = dist[k]; j = k; }
            used[j] = 1; scanned++;
            int ml = matchR[j];
            if (ml < 0) { sink = j; break; }
            const double* r2 = M + (long)ml * n;
            const double* pp = potR.data();
            double base = best - M[(long)ml * n + j] + pp[j];
            int k2 = 0;
            for (; k2 + 3 < n; k2 += 4) {
                double nd0 = base + r2[k2]   - pp[k2];
                double nd1 = base + r2[k2+1] - pp[k2+1];
                double nd2 = base + r2[k2+2] - pp[k2+2];
                double nd3 = base + r2[k2+3] - pp[k2+3];
                if (!used[k2]   && nd0 < dist[k2])   { dist[k2]   = nd0; pred[k2]   = ml; }
                if (!used[k2+1] && nd1 < dist[k2+1]) { dist[k2+1] = nd1; pred[k2+1] = ml; }
                if (!used[k2+2] && nd2 < dist[k2+2]) { dist[k2+2] = nd2; pred[k2+2] = ml; }
                if (!used[k2+3] && nd3 < dist[k2+3]) { dist[k2+3] = nd3; pred[k2+3] = ml; }
            }
            for (; k2 < n; k2++) if (!used[k2]) {
                double nd = base + r2[k2] - pp[k2];
                if (nd < dist[k2]) { dist[k2] = nd; pred[k2] = ml; }
            }
        }
        double ds = dist[sink];
        for (int j = 0; j < n; j++) if (used[j]) potR[j] += dist[j] - ds;
        int j = sink;
        while (true) {
            int L = pred[j];
            int prevj = matchL[L];
            matchL[L] = j; matchR[j] = L;
            if (L == src) break;
            j = prevj;
        }
    }
    memcpy(colOf, matchL.data(), n*sizeof(int));
}

int main() {
    int n = 600;
    vector<double> M(n*(long)n);
    FILE* f = fopen("build/M.bin","rb"); fread(M.data(), 8, n*(long)n, f); fclose(f);
    vector<int> col(n);
    auto t0 = chrono::high_resolution_clock::now();
    assign(n, M.data(), col.data());
    auto t1 = chrono::high_resolution_clock::now();
    printf("%.3f ms\n", chrono::duration<double,milli>(t1-t0).count());
    FILE* o = fopen("build/col.bin","wb"); fwrite(col.data(), 4, n, o); fclose(o);
}
