#include <cstdio>
#include <cstdint>
#include <vector>
#include <algorithm>
#include <chrono>
#include <cstring>
#include <numeric>
using namespace std;

// SSP assignment restricted to k nearest candidates per row, with fallback flag.
bool assign_cand(int n, const double* M, int k, int* colOf) {
    vector<int> cand(n*(long)k), idx(n);
    for (int i = 0; i < n; i++) {
        const double* row = M + (long)i*n;
        iota(idx.begin(), idx.end(), 0);
        nth_element(idx.begin(), idx.begin()+k-1, idx.end(), [&](int a, int b){ return row[a] < row[b]; });
        memcpy(&cand[i*(long)k], idx.data(), k*sizeof(int));
    }
    vector<int> matchL(n,-1), matchR(n,-1);
    vector<double> potR(n,0), dist(n);
    vector<int> pred(n);
    vector<int> reached(n);
    vector<char> used(n,0), inreach(n,0);

    for (int src = 0; src < n; src++) {
        int rcnt = 0;
        auto relax = [&](int j, double nd, int from) {
            if (!inreach[j]) { inreach[j] = 1; reached[rcnt++] = j; dist[j] = nd; pred[j] = from; }
            else if (nd < dist[j]) { dist[j] = nd; pred[j] = from; }
        };
        const double* row = M + (long)src*n;
        int* cc = &cand[src*(long)k];
        for (int t = 0; t < k; t++) relax(cc[t], row[cc[t]] - potR[cc[t]], src);

        int sink = -1;
        int scanned = 0;
        while (scanned < rcnt) {
            int j = -1; double best = 1e300;
            for (int t = 0; t < rcnt; t++) {
                int kk = reached[t];
                if (!used[kk] && dist[kk] < best) { best = dist[kk]; j = kk; }
            }
            if (j < 0) break;
            used[j] = 1; scanned++;
            int ml = matchR[j];
            if (ml < 0) { sink = j; break; }
            const double* r2 = M + (long)ml*n;
            double base = best - M[(long)ml*n + j] + potR[j];
            int* c2 = &cand[ml*(long)k];
            for (int t = 0; t < k; t++) {
                int kk = c2[t];
                if (used[kk]) continue;
                relax(kk, base + r2[kk] - potR[kk], ml);
            }
        }
        if (sink < 0) {
            for (int t = 0; t < rcnt; t++) { used[reached[t]] = 0; inreach[reached[t]] = 0; }
            return false;
        }
        double ds = dist[sink];
        for (int t = 0; t < rcnt; t++) {
            int j = reached[t];
            if (used[j]) potR[j] += dist[j] - ds;
            used[j] = 0; inreach[j] = 0;
        }
        int j = sink;
        while (true) {
            int L = pred[j]; int prev = matchL[L];
            matchL[L] = j; matchR[j] = L;
            if (L == src) break;
            j = prev;
        }
    }
    memcpy(colOf, matchL.data(), n*sizeof(int));
    return true;
}

int main(int argc, char** argv) {
    int k = argc>1?atoi(argv[1]):96;
    int n = 600;
    vector<double> M(n*(long)n);
    FILE* f = fopen("build/M.bin","rb"); fread(M.data(),8,n*(long)n,f); fclose(f);
    vector<int> col(n,-1);
    auto t0 = chrono::high_resolution_clock::now();
    bool ok = assign_cand(n, M.data(), k, col.data());
    auto t1 = chrono::high_resolution_clock::now();
    printf("k=%d %s %.3f ms\n", k, ok?"OK":"FAIL", chrono::duration<double,milli>(t1-t0).count());
    if (ok) { FILE* o=fopen("build/col.bin","wb"); fwrite(col.data(),4,n,o); fclose(o); }
}
