{"command":"cat > build/solver.cpp << 'EOF'
#include <dlfcn.h>
#include <cstdio>
#include <cstdint>
#include <vector>
#include <algorithm>
#include <numeric>
#include <chrono>
#include <cstring>
#include <cmath>
#include <string>
using namespace std;

typedef int (*emd_sparse_fn)(int, int, double*, double*, unsigned long long,
    unsigned long long*, unsigned long long*, double*,
    unsigned long long*, unsigned long long*, double*,
    unsigned long long*, unsigned long long,
    double*, double*, double*, unsigned long long*,
    double*, double*);

static emd_sparse_fn EMD = nullptr;

static void load() {
    const char* lib = getenv("PYLIB");
    const char* so = getenv("EMDSO");
    void* py = dlopen(lib, RTLD_NOW | RTLD_GLOBAL);
    if (!py) { fprintf(stderr, "py: %s\n", dlerror()); exit(1); }
    void* h = dlopen(so, RTLD_NOW);
    if (!h) { fprintf(stderr, "so: %s\n", dlerror()); exit(1); }
    EMD = (emd_sparse_fn)dlsym(h, "_Z15EMD_wrap_sparseiiPdS_yPyS0_S_S0_S0_S_S0_yS_S_S_yS_S_");
    if (!EMD) { fprintf(stderr, "sym: %s\n", dlerror()); exit(1); }
}

struct Res { vector<unsigned long long> fs, ft; vector<double> fv, u, v; int rc; double cost; };

static Res run_sparse(int n, double* a, vector<unsigned long long>& es, vector<unsigned long long>& et,
                      vector<double>& ec, double* uinit, double* vinit) {
    unsigned long long ne = es.size();
    unsigned long long cap = ne + 2*n + 10;
    Res r; r.fs.resize(cap); r.ft.resize(cap); r.fv.resize(cap); r.u.resize(n); r.v.resize(n);
    unsigned long long nflows = 0, result = 0; double cost = 0;
    unsigned long long max_iter = 1000000;
    int ret = EMD(n, n, a, a, ne, es.data(), et.data(), ec.data(),
                  r.fs.data(), r.ft.data(), r.fv.data(), &nflows, max_iter,
                  &cost, r.u.data(), r.v.data(), &result, uinit, vinit);
    r.fs.resize(nflows); r.ft.resize(nflows); r.fv.resize(nflows);
    r.rc = (int)result; r.cost = cost;
    (void)ret;
    return r;
}

int main(int argc, char** argv) {
    load();
    int n = 600, k = argc>1?atoi(argv[1]):160;
    vector<double> M(n*(long)n);
    FILE* f = fopen("build/M.bin","rb"); fread(M.data(), 8, n*(long)n, f); fclose(f);
    vector<double> a(n, 1.0/n);

    auto t0 = chrono::high_resolution_clock::now();
    vector<unsigned long long> es(n*(long)k), et(n*(long)k);
    vector<double> ec(n*(long)k);
    vector<int> idx(n);
    for (int i = 0; i < n; i++) {
        const double* row = M.data() + (long)i*n;
        iota(idx.begin(), idx.end(), 0);
        nth_element(idx.begin(), idx.begin()+k-1, idx.end(), [&](int x, int y){ return row[x] < row[y]; });
        for (int t = 0; t < k; t++) {
            es[i*(long)k + t] = i;
            et[i*(long)k + t] = idx[t];
            ec[i*(long)k + t] = row[idx[t]];
        }
    }
    auto t1 = chrono::high_resolution_clock::now();
    Res r = run_sparse(n, a.data(), es, et, ec, nullptr, nullptr);
    auto t2 = chrono::high_resolution_clock::now();
    // check violations
    int nviol = 0; double worst = 0;
    for (int i = 0; i < n; i++) {
        const double* row = M.data() + (long)i*n;
        for (int j = 0; j < n; j++) {
            double rc = row[j] - r.u[i] - r.v[j];
            if (rc < -1e-9) { nviol++; worst = min(worst, rc); }
        }
    }
    auto t3 = chrono::high_resolution_clock::now();
    printf("k=%d select %.2f ms solve %.2f ms check %.2f ms rc %d viol %d worst %.3e\n", k,
        chrono::duration<double,milli>(t1-t0).count(),
        chrono::duration<double,milli>(t2-t1).count(),
        chrono::duration<double,milli>(t3-t2).count(), r.rc, nviol, worst);
}
